DO $$
DECLARE
  rec RECORD;
  cur_locked BOOLEAN;
  cur_hours DECIMAL(4,1);
BEGIN
  FOR rec IN SELECT * FROM goal_events ORDER BY event_id LOOP
    SELECT is_locked, target_hours INTO cur_locked, cur_hours
    FROM goal_states
    WHERE user_id = rec.user_id;

    IF rec.event_type = 1 AND cur_locked = FALSE THEN
      UPDATE goal_states
      SET target_hours = rec.new_hours
      WHERE user_id = rec.user_id;
    ELSIF rec.event_type = 2 THEN
      UPDATE goal_states
      SET is_locked = TRUE
      WHERE user_id = rec.user_id;
    ELSIF rec.event_type = 3 THEN
      UPDATE goal_states
      SET is_locked = FALSE
      WHERE user_id = rec.user_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM goal_states ORDER BY user_id;
